    const errs = validateWithModel(doc, baseDoc, opts.schema, opts.tmpDir);
    if (errs.length) { signals.push({ kind: 'modele', texte: 'Sortie refusée par le modèle : ' + errs.slice(0, 5).join(' · ') }); delete doc.gantts; delete doc.jalons; rows.forEach((r) => { if (/créé|mis à jour/.test(r.resultat || '')) r.resultat = 'ignoré : sortie invalide'; }); }
